const esc = value => String(value ?? '').replace(/[&<>\"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', "'": '&#39;' }[character]));
const report = $json;
const products = Array.isArray(report.topProducts) ? report.topProducts.slice(0, 8) : [];
const max = Math.max(...products.map(item => Number(item.quantity) || 0), 1);
const bars = products.map((item, index) => {
  const height = Math.max(8, ((Number(item.quantity) || 0) / max) * 230);
  const x = 70 + index * 92;
  const y = 300 - height;
  return `<rect x="${x}" y="${y}" width="54" height="${height}" rx="8" fill="#5b5ce2"/><text x="${x + 27}" y="${y - 10}" text-anchor="middle" fill="#25254a" font-size="13">${esc(item.quantity)}</text><text x="${x + 27}" y="326" text-anchor="middle" fill="#555" font-size="11">${esc(String(item.product).slice(0, 11))}</text>`;
}).join('');
const html = `<!doctype html><html><head><meta charset="utf-8"><title>ScaniMart Analytics</title><style>body{font-family:Inter,Arial,sans-serif;background:#f5f7fb;color:#25254a;margin:0;padding:32px}.card{max-width:980px;margin:auto;background:white;border-radius:18px;padding:28px;box-shadow:0 8px 30px #1e24501a}h1{margin:0 0 4px}.muted{color:#71718a}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:22px 0}.metric{background:#f2f3ff;border-radius:12px;padding:16px}.metric strong{display:block;font-size:24px;margin-top:6px}svg{width:100%;height:auto;background:#fff}</style></head><body><main class="card"><h1>ScaniMart Sales Analytics</h1><div class="muted">Verified completed orders for ${esc(report.date)}</div><section class="metrics"><div class="metric">Revenue<strong>₹${Number(report.revenue || 0).toFixed(2)}</strong></div><div class="metric">Completed orders<strong>${esc(report.completedOrders)}</strong></div><div class="metric">Average order value<strong>₹${Number(report.averageOrderValue || 0).toFixed(2)}</strong></div></section><h2>Top products by quantity</h2><svg viewBox="0 0 900 360" role="img" aria-label="Top products chart"><line x1="50" y1="300" x2="850" y2="300" stroke="#cfd2e5"/>${bars || '<text x="450" y="170" text-anchor="middle" fill="#777">No product sales for this date</text>'}</svg></main></body></html>`;
return [{ json: { html } }];
